source:
"use client";
import { location as geoLocation } from "@/lib/access-log";
import "leaflet/dist/leaflet.css";
import type * as LT from "leaflet";
import { fz } from "@/lib/uiscale";
import { useEffect, useMemo, useRef, useState } from "react";
import { api, post } from "@/lib/api";
import * as M from "@/lib/maps-core";
import { formatDecimal, formatDMS } from "@/lib/coord-format";
import * as G from "@/lib/geodesy";
import * as PC from "@/lib/pluscode";
import * as GF from "@/lib/geo-formats";
import { GEONAMES_URL } from "@/lib/gazetteer-core";
import { useShell, type ModuleProps } from "../shell-context";
import { Badge, Btn } from "../ui";

/**
 * TT27 MP-01..MP-03: Maps. Leaflet 1.9 (BSD-2-Clause) draws an offline world — Natural Earth admin-0 countries from
 * world-atlas (public domain data, ISC package) — so the map works with no network at all. Street tiles from
 * tile.openstreetmap.org are opt-in (they send your IP and the area you look at to the OSM Foundation; the iframe-free
 * <img> requests carry a strict-origin Referer, which the OSM tile policy requires) or any https {z}/{x}/{y} template.
 * Places live in /Documents/Places.geojson (RFC 7946), so other GIS tools can read them.
 */
export const PLACES_PATH = "/Documents/Places.geojson";
type Mode = "pan" | "pin" | "measure";
interface CountryHit { name: string; feature: M.Feature }
/** One city from the offline gazetteer API (/api/places/search, GeoNames cities ≥ 15k people). */
interface CityResult { id: number; name: string; label: string; lat: number; lng: number; population: number; timezone: string }
interface NearResult { name: string; label: string; km: number; description: string }
/**
 * Point markers are DOM dots (divIcon), not canvas circleMarkers: during flyTo Leaflet CSS-scales the vector canvas
 * until the flight ends, which blew a 9 px circle up to fill the whole map (found by TT28 screenshot review).
 */
function dot(L: typeof LT, ll: M.LatLng, o: { size: number; fill: string; ring?: number; cls?: string; title?: string }): LT.Marker {
  const ring = o.ring ?? 2;
  return L.marker(ll, {
    keyboard: false, title: o.title ?? "",
    icon: L.divIcon({ className: `fs-maps-dot-pin ${o.cls ?? ""}`, iconSize: [o.size, o.size], iconAnchor: [o.size / 2, o.size / 2],
      html: `<span style="display:block;width:100%;height:100%;box-sizing:border-box;border-radius:50%;background:${o.fill};border:${ring}px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.45)"></span>` }),
  });
}
async function nearestCity(lat: number, lng: number, units: "metric" | "imperial"): Promise<NearResult | null> {
  try {
    const r = await fetch(`/api/places/near?lat=${lat.toFixed(5)}&lng=${lng.toFixed(5)}&units=${units}`);
    const j = await r.json() as { ok?: boolean; results?: NearResult[] };
    return j.ok ? j.results?.[0] ?? null : null;
  } catch { return null; }
}

export default function MapsModule({ win }: ModuleProps) {
  const shell = useShell();
  const host = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<LT.Map | null>(null);
  const LRef = useRef<typeof LT | null>(null);
  const feats = useRef<{ f: M.Feature; bb: [M.LatLng, M.LatLng] | null }[]>([]);
  const layers = useRef<{ countries?: LT.GeoJSON; places?: LT.LayerGroup; measure?: LT.LayerGroup; tiles?: LT.TileLayer; sel?: LT.GeoJSON; me?: LT.Marker; found?: LT.Marker }>({});
  const [ready, setReady] = useState(false);
  const [loadErr, setLoadErr] = useState("");
  const [mode, setMode] = useState<Mode>("pan");
  const modeRef = useRef<Mode>("pan");
  const [places, setPlaces] = useState<M.Places | null>(null);
  const placesRef = useRef<M.Places | null>(null);
  const dirty = useRef(false);
  const [saveErr, setSaveErr] = useState("");
  const [measure, setMeasure] = useState<M.LatLng[]>([]);
  const [closed, setClosed] = useState(false); // TT34 MP-06: treat the measured points as a closed shape → area
  // TT34 MP-07: a short Plus Code with a locality ("9G8F+6W Zürich") is recovered around that city (offline gazetteer)
  const [view, setView] = useState<{ lat: number; lng: number } | null>(null); // map centre after each move (Plus Code recovery)
  const [pcCity, setPcCity] = useState<{ q: string; lat: number; lng: number; label: string } | null>(null);
  const [cursor, setCursor] = useState<{ lat: number; lng: number; country: string } | null>(null);
  const [selCountry, setSelCountry] = useState<string>("");
  const [selPlace, setSelPlace] = useState<string | null>(null);
  const [q, setQ] = useState("");
  const [fmt, setFmt] = useState<"dd" | "dms">("dd");
  const [units, setUnits] = useState<"metric" | "imperial">("metric");
  const [status, setStatus] = useState("");
  const [cities, setCities] = useState<{ q: string; items: CityResult[] }>({ q: "", items: [] });
  const [found, setFound] = useState<CityResult | null>(null);
  const [near, setNear] = useState<{ key: string; text: string } | null>(null);
  const renamed = useRef(new Set<string>()); // places the user named by hand: never auto-renamed
  const [tileDraft, setTileDraft] = useState(shell.settings["maps.tileUrl"] ?? "");
  const tiles = shell.settings["maps.tiles"] ?? "off";
  const tileUrl = shell.settings["maps.tileUrl"] ?? "";
  const themeSetting = shell.settings["appearance.theme"];
  // TT56: "system" (ST-05) resolves through the OS colour scheme, like the shell
  const theme = themeSetting === "light" || (themeSetting === "system" && typeof window !== "undefined" && !!window.matchMedia?.("(prefers-color-scheme: light)").matches) ? "light" : "dark";

  useEffect(() => { modeRef.current = mode; }, [mode]);

  const countryAt = (lat: number, lng: number): CountryHit | null => {
    const w = M.wrapLng(lng);
    for (const { f, bb } of feats.current) {
      if (bb && (lat < bb[0][0] || lat > bb[1][0] || w < bb[0][1] || w > bb[1][1])) continue;
      if (M.inGeometry([w, lat], f.geometry)) return { name: String(f.properties?.name ?? ""), feature: f };
    }
    return null;
  };

  /* --------------------------------------------------------------- places file */
  useEffect(() => {
    let live = true;
    api<{ node: { content: string } }>(`/api/fs?op=read&path=${encodeURIComponent(PLACES_PATH)}`)
      .then((r) => { if (!live) return; let raw: unknown = null; try { raw = JSON.parse(r.node.content); } catch { setSaveErr("Places.geojson is not valid JSON — it will be replaced on the next save"); } setPlaces(M.normalizePlaces(raw)); })
      .catch((e: Error) => { if (!live) return; if (/not found|404/i.test(e.message)) setPlaces(M.emptyPlaces()); else setSaveErr(e.message); });
    return () => { live = false; };
  }, []);
  useEffect(() => {
    placesRef.current = places;
    if (!places || !dirty.current) return;
    const t = setTimeout(() => {
      dirty.current = false;
      post("/api/fs", { op: "write", path: PLACES_PATH, content: M.placesToGeoJSON(places), mime: "application/geo+json", reason: "maps" })
        .then(() => setSaveErr("")).catch((e: Error) => setSaveErr(`Save failed: ${e.message}`));
    }, 400);
    return () => clearTimeout(t);
  }, [places]);
  // flush a pending save when the tab is hidden/closed (pagehide) and on unmount — the debounce must never lose an edit
  useEffect(() => {
    const flush = () => {
      if (!dirty.current || !placesRef.current) return;
      dirty.current = false;
      const body = JSON.stringify({ op: "write", path: PLACES_PATH, content: M.placesToGeoJSON(placesRef.current), mime: "application/geo+json", reason: "maps" });
      void fetch("/api/fs", { method: "POST", headers: { "content-type": "application/json" }, body, keepalive: body.length < 60_000 }).catch(() => {});
    };
    window.addEventListener("pagehide", flush);
    return () => { window.removeEventListener("pagehide", flush); flush(); };
  }, []);
  const change = (fn: (p: M.Places) => M.Places) => setPlaces((p) => { if (!p) return p; const n = fn(p); if (n !== p) dirty.current = true; return n; });
  const newId = () => `p${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  const addAt = (lat: number, lng: number, name?: string) => {
    const id = newId();
    change((p) => M.addPlace(p, { id, name: name ?? countryAt(lat, lng)?.name ?? "", lat, lng, note: "", added: new Date().toISOString() }));
    setSelPlace(id);
    // Name it after the nearest city (offline gazetteer) when one is within 25 km, and note where it is — unless the
    // user has typed a name or note in the meantime.
    void nearestCity(lat, lng, units).then((h) => {
      if (!h) return;
      setStatus(`New place: ${h.description} (${h.label})`);
      change((p) => {
        const cur = p.places.find((x) => x.id === id); if (!cur || renamed.current.has(id)) return p;
        return M.updatePlace(p, id, { ...(name === undefined && h.km <= 25 ? { name: h.name } : {}), ...(cur.note ? {} : { note: `${h.description} · ${h.label}` }) });
      });
    });
  };
  const addRef = useRef(addAt);
  useEffect(() => { addRef.current = addAt; });


  /* ------------------------------------------------------------------- the map */
  useEffect(() => {
    let live = true; let ro: ResizeObserver | null = null;
    (async () => {
      try {
        const mod = await import("leaflet");
        const L = ((mod as unknown as { default?: typeof LT }).default ?? mod) as typeof LT;
        const [{ feature }, topoMod] = await Promise.all([import("topojson-client"), import("world-atlas/countries-50m.json")]);
        if (!live || !host.current) return;
        const topo = ((topoMod as unknown as { default?: unknown }).default ?? topoMod) as { objects: { countries: unknown } };
        const fc = feature(topo as never, topo.objects.countries as never) as unknown as { type: "FeatureCollection"; features: M.Feature[] };
        feats.current = fc.features.map((f) => ({ f, bb: M.bbox(f.geometry) })); // lookups use the raw (±180) rings
        const drawn = { ...fc, features: fc.features.map((f) => ({ ...f, geometry: M.unwrapGeometry(f.geometry) })) }; // no world-wide seam lines
        LRef.current = L;
        const map = L.map(host.current, { worldCopyJump: true, minZoom: 1, maxZoom: 18, zoomSnap: 0.5, preferCanvas: true, keyboard: true, attributionControl: true })
          .setView([30, 0], 2);
        map.attributionControl.setPrefix(false);
        map.attributionControl.addAttribution(`Borders: Natural Earth (public domain) · Places: <a href="${GEONAMES_URL}" target="_blank" rel="noopener noreferrer">GeoNames</a> (CC BY 4.0) · Leaflet`);
        layers.current.countries = L.geoJSON(drawn as never, { interactive: false }).addTo(map);
        layers.current.places = L.layerGroup().addTo(map);
        layers.current.measure = L.layerGroup().addTo(map);
        L.control.scale({ imperial: true, metric: true }).addTo(map);
        const sync = () => {
          const c = map.getCenter(), el = host.current; if (!el) return;
          el.dataset.zoom = String(map.getZoom()); el.dataset.lat = c.lat.toFixed(4); el.dataset.lng = c.lng.toFixed(4);
          setView({ lat: c.lat, lng: M.wrapLng(c.lng) });
        };
        map.on("moveend zoomend", sync); sync();
        let raf = 0;
        map.on("mousemove", (e: LT.LeafletMouseEvent) => {
          cancelAnimationFrame(raf);
          raf = requestAnimationFrame(() => setCursor({ lat: e.latlng.lat, lng: M.wrapLng(e.latlng.lng), country: countryAt(e.latlng.lat, e.latlng.lng)?.name ?? "" }));
        });
        map.on("click", (e: LT.LeafletMouseEvent) => {
          const { lat } = e.latlng, lng = M.wrapLng(e.latlng.lng);
          if (modeRef.current === "pin") addRef.current(lat, lng);
          else if (modeRef.current === "measure") setMeasure((m) => [...m, [lat, lng]]);
          else { const hit = countryAt(lat, lng); setSelCountry(hit?.name ?? ""); }
        });
        mapRef.current = map;
        host.current.dataset.countries = String(fc.features.length);
        ro = new ResizeObserver(() => map.invalidateSize());
        ro.observe(host.current);
        setReady(true);
      } catch (e) { if (live) setLoadErr(`Map failed to load: ${(e as Error).message}`); }
    })();
    return () => { live = false; ro?.disconnect(); mapRef.current?.remove(); mapRef.current = null; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // colours follow the theme; land is hidden under street tiles (borders stay as a hairline)
  useEffect(() => {
    const c = layers.current.countries; if (!ready || !c) return;
    const pal = theme === "light" ? { land: "#f3efe6", border: "#b3aa98" } : { land: "#2b3b47", border: "#5b7080" };
    c.setStyle({ color: pal.border, weight: 0.7, fillColor: pal.land, fillOpacity: tiles === "off" ? 1 : 0, opacity: tiles === "off" ? 1 : 0.35 });
  }, [ready, theme, tiles]);

  // street tiles (opt-in)
  useEffect(() => {
    const L = LRef.current, map = mapRef.current; if (!ready || !L || !map) return;
    layers.current.tiles?.remove(); layers.current.tiles = undefined;
    const url = tiles === "osm" ? M.DEFAULT_TILE_URL : tiles === "custom" && M.validTileUrl(tileUrl) ? tileUrl : "";
    if (!url) { if (host.current) host.current.dataset.tiles = "off"; return; }
    const attribution = tiles === "osm" ? `<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">${M.OSM_ATTRIBUTION}</a>` : `Tiles: ${new URL(url.replace(/\{[a-z]\}/g, "a")).hostname}`;
    layers.current.tiles = L.tileLayer(url, { maxZoom: 19, attribution, referrerPolicy: "strict-origin-when-cross-origin" } as LT.TileLayerOptions).addTo(map);
    layers.current.tiles.bringToBack();
    if (host.current) host.current.dataset.tiles = tiles;
  }, [ready, tiles, tileUrl]);

  // selected country outline
  useEffect(() => {
    const L = LRef.current, map = mapRef.current; if (!ready || !L || !map) return;
    layers.current.sel?.remove(); layers.current.sel = undefined;
    const f = feats.current.find((x) => String(x.f.properties?.name) === selCountry)?.f;
    if (f) layers.current.sel = L.geoJSON(f as never, { interactive: false, style: { color: "#0a84ff", weight: 2.2, fillColor: "#0a84ff", fillOpacity: 0.12 } }).addTo(map);
  }, [ready, selCountry]);

  // place markers
  useEffect(() => {
    const L = LRef.current, g = layers.current.places; if (!ready || !L || !g || !places) return;
    g.clearLayers();
    for (const p of places.places) {
      const sel = p.id === selPlace;
      dot(L, [p.lat, p.lng], { size: sel ? 22 : 16, fill: /^#[0-9a-f]{6}$/i.test(p.color) ? p.color : "#0a84ff", ring: sel ? 3 : 2, cls: "fs-maps-place-pin" })
        .bindTooltip(p.name, { direction: "top", offset: [0, -8] })
        .on("click", (e: LT.LeafletMouseEvent) => { L.DomEvent.stopPropagation(e); setSelPlace(p.id); })
        .addTo(g);
    }
    if (host.current) host.current.dataset.places = String(places.places.length);
  }, [ready, places, selPlace]);

  // measuring line
  useEffect(() => {
    const L = LRef.current, g = layers.current.measure; if (!ready || !L || !g) return;
    g.clearLayers();
    // TT34: geodesic curves on WGS84 (densified, longitudes unwrapped), not straight Mercator segments
    if (measure.length > 2 && closed) L.polygon(G.geodesicLine(measure, true), { color: "#ff9f0a", weight: 3, dashArray: "6 6", fillColor: "#ff9f0a", fillOpacity: 0.12, interactive: false }).addTo(g);
    else if (measure.length > 1) L.polyline(G.geodesicLine(measure), { color: "#ff9f0a", weight: 3, dashArray: "6 6", interactive: false }).addTo(g);
    measure.forEach((pt) => L.circleMarker(pt, { radius: 5, color: "#ffffff", weight: 2, fillColor: "#ff9f0a", fillOpacity: 1, interactive: false }).addTo(g));
  }, [ready, measure, closed]);

  // found-city marker
  useEffect(() => {
    const L = LRef.current, map = mapRef.current; if (!ready || !L || !map) return;
    layers.current.found?.remove(); layers.current.found = undefined;
    if (found) layers.current.found = dot(L, [found.lat, found.lng], { size: 22, fill: "#ff375f", ring: 3, cls: "fs-maps-found-pin" }).bindTooltip(found.label).addTo(map);
  }, [ready, found]);

  // "12 km NE of Raleigh" under the pointer, once it rests for 350 ms
  useEffect(() => {
    if (!cursor) return;
    const key = `${cursor.lat.toFixed(3)},${cursor.lng.toFixed(3)}`; let live = true;
    const t = setTimeout(() => { void nearestCity(cursor.lat, cursor.lng, units).then((h) => { if (live && h) setNear({ key, text: h.description }); }); }, 350);
    return () => { live = false; clearTimeout(t); };
  }, [cursor, units]);
  const nearText = cursor && near && near.key === `${cursor.lat.toFixed(3)},${cursor.lng.toFixed(3)}` ? near.text : "";

  // offline city search (debounced; results are only shown for the query they answer)
  useEffect(() => {
    const t = q.trim(); if (t.length < 2 || M.parseLatLng(t)) return;
    const ctl = new AbortController();
    const h = setTimeout(() => {
      void fetch(`/api/places/search?q=${encodeURIComponent(t)}&limit=6`, { signal: ctl.signal })
        .then((r) => r.json()).then((j: { ok?: boolean; results?: CityResult[] }) => { if (j.ok) setCities({ q: t, items: j.results ?? [] }); })
        .catch(() => {});
    }, 160);
    return () => { clearTimeout(h); ctl.abort(); };
  }, [q]);

  const pcFind = useMemo(() => PC.findCode(q), [q]);
  const [goCell, setGoCell] = useState<(PC.CodeArea & { code: string }) | null>(null);
  useEffect(() => { // fly to a chosen Plus Code cell and mark its centre
    const L = LRef.current, map = mapRef.current; if (!goCell || !L || !map) return;
    map.flyToBounds([[goCell.latLo, goCell.lngLo], [goCell.latHi, goCell.lngHi]], { maxZoom: goCell.length >= 10 ? 18 : goCell.length >= 8 ? 15 : goCell.length >= 6 ? 11 : 7 });
    layers.current.found?.remove();
    layers.current.found = dot(L, [goCell.lat, goCell.lng], { size: 16, fill: "#8e4ec6", title: goCell.code }).addTo(map);
  }, [goCell]);
  useEffect(() => {
    if (!pcFind || !PC.isShort(pcFind.code) || pcFind.rest.length < 2) return;
    const ctl = new AbortController(); const key = q;
    void fetch(`/api/places/search?q=${encodeURIComponent(pcFind.rest)}&limit=1`, { signal: ctl.signal })
      .then((r) => r.json()).then((j: { ok?: boolean; results?: CityResult[] }) => { const c = j.ok ? j.results?.[0] : undefined; if (c) setPcCity({ q: key, lat: c.lat, lng: c.lng, label: c.label }); })
      .catch(() => {});
    return () => ctl.abort();
  }, [pcFind, q]);

  /* ------------------------------------------------------------------ search */
  const results = useMemo(() => {
    const out: { label: string; go: () => void; kind: "coord" | "country" | "place" | "plus code" }[] = [];
    if (!q.trim()) return out;
    if (pcFind) {
      // full code → its cell centre; short code → nearest match to the named city, else to the map centre
      let full = "", near = "";
      if (PC.isFull(pcFind.code)) full = pcFind.code;
      else {
        const ref = pcFind.rest ? (pcCity && pcCity.q === q ? pcCity : null) : null;
        const c = ref ?? (view ? { ...view, label: "the map centre" } : null);
        if (c) { full = PC.recoverNearest(pcFind.code, c.lat, c.lng); near = ` (near ${c.label})`; }
      }
      if (full) {
        const a = PC.decode(full);
        out.push({ kind: "plus code", label: `Go to ${full}${near}`, go: () => { setFound(null); setGoCell({ code: full, ...a }); setStatus(`${full} → ${M.formatLatLng(a.lat, a.lng, fmt)} (a ${M.formatDistance(G.distance([a.latLo, a.lngLo], [a.latLo, a.lngHi]), units)} × ${M.formatDistance(G.distance([a.latLo, a.lngLo], [a.latHi, a.lngLo]), units)} cell)`); } });
      }
    }
    const c = M.parseLatLng(q);
    if (c) out.push({ kind: "coord", label: `Go to ${M.formatLatLng(c.lat, c.lng, fmt)}`, go: () => mapRef.current?.flyTo([c.lat, c.lng], c.zoom ?? Math.max(mapRef.current.getZoom(), 9)) });
    const n = q.trim().toLowerCase();
    for (const p of places?.places ?? []) if (p.name.toLowerCase().includes(n) && out.length < 12) out.push({ kind: "place", label: p.name, go: () => { setSelPlace(p.id); mapRef.current?.flyTo([p.lat, p.lng], Math.max(mapRef.current.getZoom(), 10)); } });
    if (ready) for (const f of M.searchFeatures(feats.current.map((x) => x.f), q, 8)) {
      const name = String(f.properties?.name);
      out.push({ kind: "country", label: name, go: () => { setSelCountry(name); const bb = M.mainBbox(f.geometry); if (bb && mapRef.current) mapRef.current.flyToBounds(bb, { padding: [24, 24], maxZoom: 7 }); } });
    }
    return out;
  }, [q, ready, places, fmt, pcFind, pcCity, units, view]);
  const cityHits = q.trim().length >= 2 && cities.q === q.trim() ? cities.items : [];
  const goCity = (c: CityResult) => { setFound(c); setSelPlace(null); setSelCountry(""); mapRef.current?.flyTo([c.lat, c.lng], tiles === "off" ? 7 : 11); }; // offline layer has only coastlines/borders: a regional zoom keeps context

  const centre = () => { const c = mapRef.current?.getCenter(); return c ? { lat: c.lat, lng: M.wrapLng(c.lng) } : null; };
  const locate = () => {
    if (!("geolocation" in navigator)) { setStatus("This browser has no Geolocation API."); return; }
    setStatus("Asking the browser for your location…");
    geoLocation("Maps", (pos) => {
      const L = LRef.current, map = mapRef.current; if (!L || !map) return;
      const ll: M.LatLng = [pos.coords.latitude, pos.coords.longitude];
      layers.current.me?.remove();
      layers.current.me = dot(L, ll, { size: 20, fill: "#0a84ff", ring: 3, title: "You are here" }).addTo(map);
      map.flyTo(ll, 13);
      setStatus(`You are here: ${M.formatLatLng(ll[0], ll[1], fmt)} (±${Math.round(pos.coords.accuracy)} m)`);
    }, (err) => setStatus(`Location unavailable: ${err.message || ["", "permission denied", "position unavailable", "timed out"][err.code]}`), { timeout: 10000, maximumAge: 60000 });
  };
  const exportFile = () => {
    if (!places) return;
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([M.placesToGeoJSON(places)], { type: "application/geo+json" }));
    a.download = "places.geojson"; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  };
  /** TT34 MP-08: places → GPX waypoints / KML Points; the measured path → a GPX track / KML LineString (or Polygon) */
  const exportGeo = (format: "gpx" | "kml") => {
    const doc = {
      points: (places?.places ?? []).map((p) => ({ lat: p.lat, lng: p.lng, name: p.name, note: p.note })),
      paths: measure.length > 1 ? [{ name: closed && measure.length > 2 ? "Measured area" : "Measured path", kind: (closed && measure.length > 2 ? "polygon" : "track") as GF.GeoPath["kind"], points: measure.map(([lat, lng]) => ({ lat, lng })) }] : [],
    };
    const text = format === "gpx" ? GF.toGPX(doc, { name: "Fusion Maps", time: new Date().toISOString() }) : GF.toKML(doc, { name: "Fusion Maps" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([text], { type: format === "gpx" ? "application/gpx+xml" : "application/vnd.google-earth.kml+xml" }));
    a.download = `places.${format}`; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000);
    setStatus(`Exported ${doc.points.length} place(s)${doc.paths.length ? " and the measured path" : ""} as ${format.toUpperCase()}`);
  };
  /** GPX / KML text → places (waypoints) + the first path into Measure */
  function importGeoText(text: string, label: string) {
    let d: ReturnType<typeof GF.parseGeoFile>;
    try { d = GF.parseGeoFile(text); } catch (e) { setStatus(`${label}: ${(e as Error).message}`); return; }
    const inc = d.points.slice(0, M.PLACES_MAX);
    change((p) => inc.reduce((acc, x) => M.addPlace(acc, { id: newId(), name: x.name.trim() || "Waypoint", note: x.note, lat: x.lat, lng: M.wrapLng(x.lng), added: new Date().toISOString() }), p));
    const path = d.paths[0];
    if (path) {
      setMeasure(path.points.map((x) => [x.lat, M.wrapLng(x.lng)] as M.LatLng)); setClosed(path.kind === "polygon"); setMode("measure");
      const L = LRef.current, map = mapRef.current;
      if (L && map) { const ll = path.points.map((x) => [x.lat, x.lng] as M.LatLng); map.flyToBounds(L.latLngBounds(ll), { padding: [24, 24], maxZoom: 15 }); }
    }
    const more = d.paths.length > 1 ? ` (${d.paths.length - 1} more path(s) not loaded: Measure holds one)` : "";
    setStatus(`Imported ${inc.length} place(s)${path ? ` and “${path.name}” (${path.points.length} points)` : ""} from ${label}${more}${d.warnings.length ? ` · ${d.warnings.length} warning(s): ${d.warnings[0]}` : ""}`);
  }

  const importFile = async (file: File) => {
    let raw: unknown = null;
    const text = await file.text();
    if (/\.(gpx|kml)$/i.test(file.name) || /^\s*(<\?xml|<gpx|<kml)/.test(text)) { importGeoText(text, file.name); return; }
    try { raw = JSON.parse(text); } catch { setStatus(`${file.name} is not valid JSON`); return; }
    const inc = M.normalizePlaces(raw).places;
    change((p) => inc.reduce((acc, x) => M.addPlace(acc, { ...x, id: newId() }), p));
    setStatus(`Imported ${inc.length} place(s) from ${file.name}`);
  };

  // a .geojson / .gpx / .kml handed over by Files ("Open with Maps") is merged into the places
  const openPath = (win.props.path as string) ?? "";
  useEffect(() => {
    if (!openPath || openPath === PLACES_PATH || !places) return;
    let live = true;
    api<{ node: { content: string } }>(`/api/fs?op=read&path=${encodeURIComponent(openPath)}`).then((r) => {
      if (!live) return;
      if (/\.(gpx|kml)$/i.test(openPath)) { importGeoText(r.node.content, openPath.split("/").pop() ?? openPath); return; }
      let raw: unknown = null; try { raw = JSON.parse(r.node.content); } catch { setStatus(`${openPath} is not valid JSON`); return; }
      const inc = M.normalizePlaces(raw).places;
      change((p) => inc.reduce((acc, x) => M.addPlace(acc, { ...x, id: newId() }), p));
      setStatus(`Imported ${inc.length} place(s) from ${openPath.split("/").pop()}`);
    }).catch((e: Error) => setStatus(e.message));
    return () => { live = false; };
    // run once when the places file has loaded
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openPath, places === null]);

  const sel = places?.places.find((p) => p.id === selPlace) ?? null;
  const dist = G.pathLength(measure); // TT34 MP-06: WGS84 ellipsoid (Vincenty + shooting), not the sphere
  const shape = closed && measure.length > 2 ? G.polygonArea(measure) : null;

  return (
    <div className="fs-maps" data-testid="mp-app">
      <aside className="fs-maps-side" aria-label="Map tools">
        <div className="fs-maps-search">
          <input className="fs-input" data-testid="mp-search" value={q} onChange={(e) => setQ(e.target.value)} spellCheck={false}
            onKeyDown={(e) => { if (e.key === "Enter" && (results[0] || cityHits[0])) { e.preventDefault(); if (results[0]) results[0].go(); else goCity(cityHits[0]); } }}
            placeholder="City, country, place, coordinates or Plus Code" aria-label="Search cities, countries, saved places, coordinates or Plus Codes" />
          {results.length || cityHits.length ? (
            <ul className="fs-maps-results" data-testid="mp-results">
              {results.map((r, i) => <li key={`${r.kind}${i}`}><button type="button" className="fs-maps-result" data-testid="mp-result" data-kind={r.kind} onClick={r.go}>{r.label}<span className="fs-dim">{r.kind}</span></button></li>)}
              {cityHits.map((c) => <li key={`city${c.id}`}><button type="button" className="fs-maps-result" data-testid="mp-result" data-kind="city" onClick={() => goCity(c)}>{c.label}<span className="fs-dim">city</span></button></li>)}
            </ul>
          ) : null}
        </div>

        <div role="radiogroup" aria-label="Map click does" className="fs-maps-modes">
          {(["pan", "pin", "measure"] as const).map((m) => (
            <label key={m} className="fs-layout-opt" data-checked={mode === m}>
              <input type="radio" name={`mp-mode-${win.id}`} className="fs-visually-hidden-radio" checked={mode === m} onChange={() => setMode(m)} data-testid={`mp-mode-${m}`} />
              {m === "pan" ? "Explore" : m === "pin" ? "Add place" : "Measure"}
            </label>
          ))}
        </div>

        {mode === "measure" ? (
          <div className="fs-maps-card" data-testid="mp-measure-card">
            <strong data-testid="mp-measure" data-metres={Math.round(dist)}>{measure.length > 1 ? M.formatDistance(dist, units) : "Click the map to add points"}</strong>
            {measure.length > 1 ? <span className="fs-dim">{measure.length} points · first leg bearing {Math.round(G.inverse(measure[0], measure[1]).az1 + 360) % 360}° · WGS84 ellipsoid</span> : null}
            <label className="fs-row" style={{ gap: 8 }}><input type="checkbox" checked={closed} onChange={(e) => setClosed(e.target.checked)} data-testid="mp-measure-closed" />Closed shape (area)</label>
            {shape ? <span data-testid="mp-area" data-m2={Math.round(shape.area)} data-perimeter={Math.round(shape.perimeter)}>Area <strong>{G.formatArea(shape.area, units)}</strong> · perimeter {M.formatDistance(shape.perimeter, units)}</span> : closed ? <span className="fs-dim">Add 3 or more points for an area</span> : null}
            <div className="fs-row" style={{ gap: 6, flexWrap: "wrap" }}>
              <Btn onClick={() => { const c = centre(); if (c) setMeasure((m) => [...m, [c.lat, c.lng]]); }} data-testid="mp-measure-centre">Add map centre</Btn>
              <Btn variant="ghost" onClick={() => setMeasure((m) => m.slice(0, -1))} disabled={!measure.length}>Undo point</Btn>
              <Btn variant="ghost" onClick={() => setMeasure([])} disabled={!measure.length} data-testid="mp-measure-clear">Clear</Btn>
            </div>
          </div>
        ) : null}
        {found ? (
          <div className="fs-maps-card" data-testid="mp-found" data-city={found.name}>
            <strong>{found.label}</strong>
            <span className="fs-dim">Population {found.population.toLocaleString("en-US")} · {found.timezone.replace(/_/g, " ")} · {M.formatLatLng(found.lat, found.lng, fmt)} · Plus Code {PC.encode(found.lat, found.lng)}</span>
            <div className="fs-row" style={{ gap: 6 }}>
              <Btn onClick={() => { addAt(found.lat, found.lng, found.name); setFound(null); }} disabled={!places} data-testid="mp-found-save">Save as place</Btn>
              <Btn variant="ghost" onClick={() => setFound(null)}>Close</Btn>
            </div>
            <span className="fs-dim" style={{ fontSize: fz(11.5) }}>City-level search, offline: cities of 15,000+ people from <a href={GEONAMES_URL} target="_blank" rel="noopener noreferrer">GeoNames</a> (CC BY 4.0). No street addresses.</span>
          </div>
        ) : null}
        {selCountry && mode === "pan" ? <div className="fs-maps-card" data-testid="mp-country"><strong>{selCountry}</strong><span className="fs-dim">Selected country (Natural Earth borders)</span></div> : null}

        <div className="fs-row" style={{ gap: 8 }}>
          <strong style={{ fontSize: fz(14) }}>Places</strong><Badge>{places?.places.length ?? "…"}</Badge><span style={{ flex: 1 }} />
          <Btn variant="ghost" onClick={() => { const c = centre(); if (c) addAt(c.lat, c.lng); }} disabled={!ready || !places} data-testid="mp-add-centre" title="Add a place at the centre of the map (keyboard alternative to clicking the map)">Add at centre</Btn>
        </div>
        <ul className="fs-maps-places" data-testid="mp-places">
