"use client";
import { fz } from "@/lib/uiscale";

import { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { api, fmtBytes, post } from "@/lib/api";
import {
  clearBrowserStorage,
  inspectBrowserStorage,
  type BrowserBucketReport,
  type BucketStat,
  type ServerBucketId,
  type UninstallPreview,
} from "@/lib/storage-core";
import { useShell, type ModuleProps } from "../shell-context";
import { Badge, Btn, KV, Section } from "../ui";
import { reclaimSummary } from "@/lib/reclaim-summary";

interface Data {
  categories: { category: string; files: number; bytes: number }[];
  large: { path: string; size: number; mime: string }[];
  duplicates: { sha256: string; copies: number; size: number; reclaimable: number; paths: string[] }[];
  trash: { files: number; bytes: number };
  versions: { versions: number; bytes: number };
  buckets?: BucketStat[];
}

/** FM-07: logical VFS usage AND the browser's real origin quota, plus AP-02 per-bucket uninstall assistant. */
export default function StorageModule(_: ModuleProps) {
  const shell = useShell();
  const [d, setD] = useState<Data | null>(null);
  const [quota, setQuota] = useState<{ usage: number; quota: number } | null>(null);
  const [persisted, setPersisted] = useState<boolean | null>(null);
  const [browserLocal, setBrowserLocal] = useState<BrowserBucketReport>({ keys: [], rows: 0, bytes: 0, samples: [] });
  const [selected, setSelected] = useState<Set<ServerBucketId>>(new Set());
  const [includeBrowser, setIncludeBrowser] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewData, setPreviewData] = useState<UninstallPreview | null>(null);
  const [confirmText, setConfirmText] = useState("");
  const [busy, setBusy] = useState(false);
  const [lastResult, setLastResult] = useState<string>("");
  const previewBtnRef = useRef<HTMLButtonElement | null>(null);
  const confirmInputRef = useRef<HTMLInputElement | null>(null);
  const modalRef = useRef<HTMLElement | null>(null);

  const refreshBrowserStorage = useCallback(() => {
    if (typeof window === "undefined") return;
    const loc = inspectBrowserStorage(window.localStorage);
    const ses = inspectBrowserStorage(window.sessionStorage);
    const keys = [...loc.keys.map((k) => `local:${k}`), ...ses.keys.map((k) => `session:${k}`)];
    setBrowserLocal({
      keys,
      rows: loc.rows + ses.rows,
      bytes: loc.bytes + ses.bytes,
      samples: keys.slice(0, 5),
    });
  }, []);

  const load = useCallback(() => {
    refreshBrowserStorage();
    return api<Data>("/api/storage").then(setD).catch(() => undefined);
  }, [refreshBrowserStorage]);

  useEffect(() => {
    void load();
    navigator.storage?.estimate?.().then((e) => setQuota({ usage: e.usage ?? 0, quota: e.quota ?? 0 })).catch(() => undefined);
    navigator.storage?.persisted?.().then(setPersisted).catch(() => undefined);
  }, [shell.refreshTick, load]);

  const total = d?.categories.reduce((a, c) => a + Number(c.bytes), 0) ?? 0;
  const buckets = d?.buckets ?? [];

  const toggleBucket = (id: ServerBucketId) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const selectNonEmpty = () => {
    const next = new Set<ServerBucketId>();
    for (const b of buckets) if (b.rows > 0) next.add(b.id);
    setSelected(next);
    setIncludeBrowser(browserLocal.rows > 0);
  };

  const clearSelection = () => {
    setSelected(new Set());
    setIncludeBrowser(false);
  };

  const openPreview = async () => {
    if (selected.size === 0 && !includeBrowser) return;
    setBusy(true);
    try {
      let serverPreview: UninstallPreview = { buckets: [], totalRows: 0, totalBytes: 0, samples: [] };
      if (selected.size > 0) {
        const res = await post<{ ok: boolean; preview: UninstallPreview }>("/api/storage", {
          op: "preview",
          buckets: [...selected],
        });
        serverPreview = res.preview;
      }
      refreshBrowserStorage();
      setPreviewData(serverPreview);
      setConfirmText("");
      setPreviewOpen(true);
      requestAnimationFrame(() => confirmInputRef.current?.focus());
    } catch (e) {
      shell.toast(`Could not build preview: ${(e as Error).message}`, "bad");
    } finally {
      setBusy(false);
    }
  };

  const closePreview = () => {
    setPreviewOpen(false);
    setConfirmText("");
    requestAnimationFrame(() => previewBtnRef.current?.focus());
  };

  const executePurge = async () => {
    if (confirmText !== "DELETE" || busy) return;
    setBusy(true);
    try {
      let rowsRemoved = 0;
      let bytesRemoved = 0;
      if (selected.size > 0) {
        const res = await post<{ ok: boolean; purged: UninstallPreview; buckets: BucketStat[] }>("/api/storage", {
          op: "purge",
          buckets: [...selected],
          confirm: "DELETE",
        });
        rowsRemoved += res.purged.totalRows;
        bytesRemoved += res.purged.totalBytes;
      }
      if (includeBrowser && typeof window !== "undefined") {
        const l = clearBrowserStorage(window.localStorage);
        const s = clearBrowserStorage(window.sessionStorage);
        rowsRemoved += l.removed + s.removed;
        bytesRemoved += l.bytesFreed + s.bytesFreed;
      }
      setPreviewOpen(false);
      setConfirmText("");
      setSelected(new Set());
      setIncludeBrowser(false);
      setLastResult(`Purged ${rowsRemoved} item(s) (${fmtBytes(bytesRemoved)}) across selected buckets.`);
      await load();
      shell.bumpRefresh();
      requestAnimationFrame(() => previewBtnRef.current?.focus());
    } catch (e) {
      shell.toast(`Purge failed: ${(e as Error).message}`, "bad");
    } finally {
      setBusy(false);
    }
  };

  const previewTotalRows = (previewData?.totalRows ?? 0) + (includeBrowser ? browserLocal.rows : 0);
  const previewTotalBytes = (previewData?.totalBytes ?? 0) + (includeBrowser ? browserLocal.bytes : 0);

  return (
    <div className="fs-scroll" data-testid="storage-app" style={{ padding: 10, display: "grid", gap: 10, alignContent: "start", height: "100%" }}>
      <Section title="Where the bytes are" right={<Btn variant="ghost" aria-label="Refresh storage overview" onClick={() => void load()}>Refresh</Btn>}>
        <KV k="VFS files (server, Postgres)" v={fmtBytes(total)} />
        <KV k="Trash" v={`${d?.trash.files ?? 0} files · ${fmtBytes(Number(d?.trash.bytes ?? 0))}`} />
        <KV k="Version history" v={`${d?.versions.versions ?? 0} snapshots · ${fmtBytes(Number(d?.versions.bytes ?? 0))}`} />
        <KV k="Browser origin storage" v={quota ? `${fmtBytes(quota.usage)} of ${fmtBytes(quota.quota)}` : "unavailable"} />
        <KV k="Eviction protection" v={persisted === null ? "unknown" : persisted ? <Badge tone="ok">persisted</Badge> : (
          <Btn variant="ghost" onClick={async () => setPersisted(await navigator.storage.persist())}>not persisted — request</Btn>
        )} />
        <div style={{ display: "flex", height: 10, borderRadius: 5, overflow: "hidden", background: "rgba(255,255,255,.06)" }}>
          {d?.categories.map((c, i) => (
            <div key={c.category} title={`${c.category} ${fmtBytes(Number(c.bytes))}`}
              style={{ width: `${(Number(c.bytes) / Math.max(total, 1)) * 100}%`, background: ["#5b8cff", "#b14bff", "#39d98a", "#ffc453", "#ff6b6b", "#3cc", "#999"][i % 7] }} />
          ))}
        </div>
        <div className="fs-row" style={{ gap: 4, flexWrap: "wrap" }} data-testid="storage-categories">
          {d?.categories.map((c) => <Badge key={c.category}>{c.category}: {c.files} · {fmtBytes(Number(c.bytes))}</Badge>)}
        </div>
      </Section>

      <Section title="Duplicates (by content digest)">
        {d?.duplicates.length ? (() => { const sum = reclaimSummary(d.duplicates.map((g) => ({ copies: g.copies, reclaimable: Number(g.reclaimable) }))); return <Badge tone="warn" data-testid="storage-reclaim-summary">{sum.groups} duplicate groups · {sum.copies} copies · reclaim {fmtBytes(sum.bytes)}</Badge>; })() : null}
        {d?.duplicates.length ? d.duplicates.map((g) => (
          <div key={g.sha256} className="fs-panel" data-testid="storage-duplicate-group" style={{ padding: 8, display: "grid", gap: 3 }}>
            <div className="fs-row" style={{ justifyContent: "space-between" }}>
              <span className="fs-mono" style={{ fontSize: fz(11) }}>{g.sha256.slice(0, 12)} · {g.copies} copies</span>
              <Badge tone="warn">reclaim {fmtBytes(Number(g.reclaimable))}</Badge>
            </div>
            {g.paths.map((p, i) => (
              <div key={p} className="fs-row" style={{ justifyContent: "space-between" }}>
                <span className="fs-mono" style={{ fontSize: fz(11) }}>{p}</span>
                {i > 0 ? <Btn variant="ghost" onClick={async () => { await post("/api/fs", { op: "trash", path: p }); shell.bumpRefresh(); }}>Trash</Btn> : <Badge tone="ok">keep</Badge>}
              </div>
            ))}
          </div>
        )) : <div className="fs-dim" style={{ fontSize: fz(11.5) }}>No duplicate content.</div>}
      </Section>

      <Section title="Largest files">
        {d?.large.map((f) => (
          <div key={f.path} className="fs-row" style={{ justifyContent: "space-between" }}>
            <button className="fs-mono" style={{ fontSize: fz(11), background: "none", border: 0, color: "inherit", cursor: "pointer", textAlign: "left" }}
              onClick={() => shell.open("peek", { path: f.path, title: f.path })}>{f.path}</button>
            <span className="fs-dim" style={{ fontSize: fz(11) }}>{fmtBytes(Number(f.size))}</span>
          </div>
        ))}
      </Section>

      <Section
        title="Uninstall & data assistant (AP-02)"
        right={
          <div className="fs-row" style={{ gap: 6 }}>
            <Btn variant="ghost" data-testid="storage-select-nonempty" onClick={selectNonEmpty}>Select non-empty</Btn>
            <Btn variant="ghost" data-testid="storage-clear-selection" onClick={clearSelection}>Clear selection</Btn>
          </div>
        }
      >
        <div className="fs-dim" style={{ fontSize: fz(11.5) }}>
          Choose which Fusion data buckets to remove. Nothing is deleted until you inspect the live row-count preview and confirm. System specifications and templates in /System are protected.
        </div>
        <div style={{ display: "grid", gap: 6 }} data-testid="storage-buckets">
          {buckets.map((b) => (
            <label
              key={b.id}
              data-testid={`storage-bucket-row-${b.id}`}
              className="fs-panel"
              style={{ padding: "6px 8px", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, cursor: "pointer" }}
            >
              <span style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <input
                  type="checkbox"
                  data-testid={`storage-bucket-${b.id}`}
                  checked={selected.has(b.id)}
                  onChange={() => toggleBucket(b.id)}
                />
                <span>
                  <strong style={{ fontSize: fz(12) }}>{b.label}</strong>
                  <span className="fs-dim" style={{ display: "block", fontSize: fz(11) }}>{b.description}</span>
                </span>
              </span>
              <span className="fs-mono" data-testid={`storage-bucket-stat-${b.id}`} style={{ fontSize: fz(11), whiteSpace: "nowrap" }}>
                {b.rows} rows · {fmtBytes(b.bytes)}
              </span>
            </label>
          ))}
          <label
            data-testid="storage-bucket-row-browser"
            className="fs-panel"
            style={{ padding: "6px 8px", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, cursor: "pointer" }}
          >
            <span style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <input
                type="checkbox"
                data-testid="storage-bucket-browser"
                checked={includeBrowser}
                onChange={(e) => setIncludeBrowser(e.target.checked)}
              />
              <span>
                <strong style={{ fontSize: fz(12) }}>Browser local &amp; session storage</strong>
                <span className="fs-dim" style={{ display: "block", fontSize: fz(11) }}>Client-side drafts, user dictionary words and UI caches stored in this browser</span>
              </span>
            </span>
            <span className="fs-mono" data-testid="storage-bucket-stat-browser" style={{ fontSize: fz(11), whiteSpace: "nowrap" }}>
              {browserLocal.rows} keys · {fmtBytes(browserLocal.bytes)}
            </span>
          </label>
        </div>
        <div className="fs-row" style={{ justifyContent: "space-between", alignItems: "center", marginTop: 4 }}>
          <span style={{ fontSize: fz(11.5) }} data-testid="storage-uninstall-status">{lastResult}</span>
          <Btn
            ref={previewBtnRef}
            variant="danger"
            data-testid="storage-uninstall-preview"
            disabled={(selected.size === 0 && !includeBrowser) || busy}
            onClick={() => void openPreview()}
          >
            Preview what will be deleted…
          </Btn>
        </div>
      </Section>

      {previewOpen && typeof document !== "undefined" && createPortal(
        <div
          style={{ position: "fixed", inset: 0, zIndex: 10000, background: "rgba(0,0,0,.45)", display: "grid", placeItems: "center", padding: 16 }}
          onMouseDown={(e) => { if (e.target === e.currentTarget) closePreview(); }}
          onKeyDown={(e) => {
            e.stopPropagation();
            if (e.key === "Escape") {
              e.preventDefault();
              closePreview();
              return;
            }
            if (e.key === "Tab" && modalRef.current) {
              const focusables = [...modalRef.current.querySelectorAll<HTMLElement>('input, button:not([disabled])')];
              if (focusables.length === 0) return;
              const idx = focusables.indexOf(document.activeElement as HTMLElement);
              const next = e.shiftKey
                ? (idx <= 0 ? focusables.length - 1 : idx - 1)
                : (idx < 0 || idx >= focusables.length - 1 ? 0 : idx + 1);
              e.preventDefault();
              focusables[next]?.focus();
            }
          }}
        >
          <section
            ref={modalRef}
            role="dialog"
            aria-modal="true"
            aria-label="Uninstall data preview"
            data-testid="storage-uninstall-modal"
            style={{ width: "min(460px, 100%)", padding: 18, borderRadius: 12, color: "var(--fs-text, #eef2ff)", background: "var(--fs-panel-solid, #121a2e)", border: "1px solid var(--fs-border)", boxShadow: "0 12px 48px rgba(0,0,0,.4)", display: "grid", gap: 12 }}
          >
            <div className="fs-row" style={{ justifyContent: "space-between", alignItems: "center" }}>
              <h2 style={{ margin: 0, fontSize: fz(16) }}>What will be deleted</h2>
              <Btn variant="ghost" data-testid="storage-uninstall-cancel" onClick={closePreview}>Cancel</Btn>
            </div>
            <div style={{ fontSize: fz(12) }}>
              Live count across selected buckets: <strong data-testid="storage-preview-rows">{previewTotalRows}</strong> item(s) totaling <strong data-testid="storage-preview-bytes">{fmtBytes(previewTotalBytes)}</strong>.
            </div>
            <dl style={{ margin: 0, display: "grid", gridTemplateColumns: "1fr auto", gap: "6px 12px", fontSize: fz(12) }}>
              {previewData?.buckets.map((b) => (
                <div key={b.id} style={{ display: "contents" }}>
                  <dt style={{ fontWeight: 600 }}>{b.label}</dt>
                  <dd data-testid={`storage-preview-bucket-${b.id}`} style={{ margin: 0, textAlign: "right" }}>{b.rows} rows · {fmtBytes(b.bytes)}</dd>
                </div>
              ))}
              {includeBrowser && (
                <div style={{ display: "contents" }}>
                  <dt style={{ fontWeight: 600 }}>Browser local &amp; session storage</dt>
                  <dd data-testid="storage-preview-bucket-browser" style={{ margin: 0, textAlign: "right" }}>{browserLocal.rows} keys · {fmtBytes(browserLocal.bytes)}</dd>
                </div>
              )}
            </dl>
            {(previewData?.samples.length || (includeBrowser && browserLocal.samples.length)) ? (
              <div className="fs-panel" style={{ padding: 8, fontSize: fz(11) }} data-testid="storage-preview-samples">
                <div style={{ fontWeight: 600, marginBottom: 4 }}>Sample items to be removed:</div>
                <ul style={{ margin: 0, paddingLeft: 18 }}>
                  {previewData?.samples.slice(0, 6).map((s, i) => <li key={i} className="fs-mono">{s}</li>)}
                  {includeBrowser && browserLocal.samples.slice(0, 3).map((s, i) => <li key={`b-${i}`} className="fs-mono">Browser: {s}</li>)}
                </ul>
              </div>
            ) : null}
            <label style={{ display: "grid", gap: 4, fontSize: fz(12) }}>
              <span>Type <strong>DELETE</strong> to confirm permanent removal:</span>
              <input
                ref={confirmInputRef}
                type="text"
                className="fs-input"
                data-testid="storage-uninstall-confirm"
                aria-label="Type DELETE to confirm"
                value={confirmText}
                onChange={(e) => setConfirmText(e.target.value)}
                onKeyDown={(e) => { if (e.key === "Enter" && confirmText === "DELETE") { e.preventDefault(); void executePurge(); } }}
              />
            </label>
            <div className="fs-row" style={{ justifyContent: "flex-end", gap: 8 }}>
              <Btn
                variant="danger"
                data-testid="storage-uninstall-execute"
                disabled={confirmText !== "DELETE" || busy}
                onClick={() => void executePurge()}
              >
                Permanently delete selected data
              </Btn>
            </div>
          </section>
        </div>,
        document.body,
      )}
    </div>
  );
}

"use client";
import { fz } from "@/lib/uiscale";
import { UiGlyph } from "../AppIcon";
import { useEffect, useMemo, useRef, useState } from "react";
import { api, post } from "@/lib/api";
import * as S from "@/lib/stream-core";
import * as E from "@/lib/embed-control-core";
import { useShell, type ModuleProps } from "../shell-context";
import { Badge, Btn } from "../ui";
import { askText } from "@/lib/ask";
import { showOsd } from "@/lib/osd";

/**
 * TT27 SM-01 / SM-02 / SM-03: the Video and Music players. Both are the providers' *official* embed players in an
 * iframe (no scraping, no proxy, no SDK bundled) plus native <video>/<audio> for direct files, a click-to-load
 * privacy gate (nothing contacts a provider until you choose), and one shared library file /Documents/Streams.json.
 *
 * Referrer: the site sends Referrer-Policy: no-referrer globally; provider iframes (YouTube rejects embeds without a
 * Referer — "Error 153") opt in per element to strict-origin-when-cross-origin, which sends only this origin.
 */
const Ico = ({ d }: { d: string }) => (
  <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false" style={{ width: fz(14), height: fz(14) }}>
    <path d={d} fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);
const PENCIL = "M3 13l1-3.5L11 2.5l2.5 2.5L6.5 12z", UP = "M8 13V3M3.5 7.5L8 3l4.5 4.5", CROSS = "M4 4l8 8M12 4l-8 8";

export const LIBRARY_PATH = "/Documents/Streams.json";
import { loadPlays, storePlays, pushPlay, type RecentPlay } from "@/lib/recent-plays";
import { providersOf, filterByProvider } from "@/lib/provider-filter";
import { sortLibrary, type LibrarySort } from "@/lib/library-sort";
import { libraryStats } from "@/lib/library-stats";
const STATUS_LABEL: Record<E.Status, string> = { loading: "Loading", ready: "Ready", cued: "Ready", playing: "Playing", paused: "Paused", buffering: "Buffering", ended: "Ended" };
/** TT33: a one-way player (TIDAL) reports starts only — say exactly what is known */
const statusText = (c: E.CtlState) => c.oneWay
  ? (c.status === "playing" ? "Started" : c.status === "paused" && c.assumed ? "Pause sent" : STATUS_LABEL[c.status])
  : `${STATUS_LABEL[c.status]} · ${E.formatClock(c.time, c.duration)}`;
/** TT33: one player at a time across every Video / Music window (a start anywhere pauses the others) */
const EXCLUSIVE = "fusion-media-exclusive";

const EXAMPLES: Record<S.StreamKind, string[]> = {
  video: ["https://www.youtube.com/watch?v=…", "https://vimeo.com/…", "https://<peertube-instance>/w/…", "https://tidal.com/video/…", "https://….mp4"],
  audio: ["https://open.spotify.com/track/…", "https://soundcloud.com/artist/track", "https://tidal.com/album/…", "https://open.qobuz.com/album/…", "https://music.amazon.com/albums/…", "an embed code <iframe …>", "https://….mp3"],
};

export function StreamApp({ win, kind }: ModuleProps & { kind: S.StreamKind }) {
  const shell = useShell();
  const pfx = kind === "video" ? "sv" : "sa";
  const [url, setUrl] = useState<string>((win.props.url as string) ?? "");
  const [current, setCurrent] = useState<{ ref: S.StreamRef; itemId: string | null } | null>(null);
  const [error, setError] = useState("");
  const [lib, setLib] = useState<S.Library | null>(null);
  const [libErr, setLibErr] = useState("");
  const [q, setQ] = useState("");
  const [consented, setConsented] = useState<Set<string>>(() => new Set());
  const [remember, setRemember] = useState(false);
  const [loop, setLoop] = useState(false);
  // TT34 SM-11: shuffle (no repeats within a round) + a history so Previous retraces shuffled picks
  const [shuffle, setShuffle] = useState(false);
  const history = useRef<string[]>([]);
  const played = useRef<string[]>([]);
  // TT34 SM-09: native <video>/<audio> state for the shared transport (embeds report through `ctl`)
  const [media, setMedia] = useState<{ time: number; duration: number; volume: number; muted: boolean; rate: number; paused: boolean } | null>(null);
  // TT28 SM-04: two-way control of the embed (ended → auto-next, play/pause, progress) — see embed-control-core.ts
  const [autoNext, setAutoNext] = useState(true);
  const [ctl, setCtl] = useState<E.CtlState | null>(null);
  const ctlRef = useRef<E.CtlState | null>(null);
  const frameRef = useRef<HTMLIFrameElement | null>(null);
  /** the iframe's identity: a new key/src only when a NEW player is needed (a same-player load keeps the frame) */
  const [plays, setPlays] = useState<RecentPlay[]>(() => { try { return loadPlays(localStorage); } catch { return []; } });
  const [frame, setFrame] = useState<{ key: number; src: string; ctl: E.Ctl | null } | null>(null);
  const frameSeq = useRef(0);
  const mediaRef = useRef<HTMLMediaElement | null>(null);
  const selfId = useRef(`${win.id}`);
  const autoplayNext = useRef(false);
  const dirty = useRef(false);
  const libRef = useRef<S.Library | null>(null);
  const alwaysLoad = shell.settings["media.embeds"] === "allow";
  const parentHost = typeof window === "undefined" ? "localhost" : window.location.hostname;

  // load the shared library (a missing file is an empty library)
  useEffect(() => {
    let live = true;
    api<{ node: { content: string } }>(`/api/fs?op=read&path=${encodeURIComponent(LIBRARY_PATH)}`)
      .then((r) => { if (!live) return; let raw: unknown = null; try { raw = JSON.parse(r.node.content); } catch { setLibErr("Streams.json is not valid JSON — it will be replaced on the next save"); } setLib(S.normalizeLibrary(raw)); })
      .catch((e: Error) => { if (!live) return; if (/not found|404/i.test(e.message)) setLib(S.emptyLibrary()); else setLibErr(e.message); });
    return () => { live = false; };
  }, []);

  // debounced save; flushed on unmount (keepalive capped below the 64 KiB browser limit)
  useEffect(() => {
    libRef.current = lib;
    if (!lib || !dirty.current) return;
    const t = setTimeout(() => {
      dirty.current = false;
      post("/api/fs", { op: "write", path: LIBRARY_PATH, content: JSON.stringify(lib, null, 1), mime: "application/json", reason: "streams" })
        .then(() => setLibErr("")).catch((e: Error) => setLibErr(`Save failed: ${e.message}`));
    }, 400);
    return () => clearTimeout(t);
  }, [lib]);
  // flush a pending save when the tab is hidden/closed (pagehide) and on unmount — the debounce must never lose an edit
  useEffect(() => {
    const flush = () => {
      if (!dirty.current || !libRef.current) return;
      dirty.current = false;
      const body = JSON.stringify({ op: "write", path: LIBRARY_PATH, content: JSON.stringify(libRef.current, null, 1), mime: "application/json", reason: "streams" });
      void fetch("/api/fs", { method: "POST", headers: { "content-type": "application/json" }, body, keepalive: body.length < 60_000 }).catch(() => {});
    };
    window.addEventListener("pagehide", flush);
    return () => { window.removeEventListener("pagehide", flush); flush(); };
  }, []);
  const change = (next: S.Library) => { dirty.current = true; setLib(next); };

  const play = (raw: string, itemId: string | null = null) => {
    const p = S.parseStream(raw, parentHost);
    if (!p.ok) { setError(p.error); return; }
    if (p.ref.kind !== kind) { setError(`That is a ${p.ref.kind === "audio" ? "music" : "video"} link — open it in ${p.ref.kind === "audio" ? "Music" : "Video"}.`); return; }
    setError("");
    const c = E.controllable(p.ref.provider);
    const origin = typeof window === "undefined" ? "" : window.location.origin;
    // same YouTube player already connected → load the new video into it (keeps the browser's playback permission)
    const live = ctlRef.current, cur = frame;
    if (c === "youtube" && cur?.ctl === "youtube" && live?.connected && frameRef.current?.contentWindow && p.ref.sub !== "playlist") {
      const msg = E.command("youtube", { op: "load", id: p.ref.id, start: p.ref.start ?? 0 });
      const to = E.targetOrigin("youtube", cur.src);
      if (msg && to) {
        frameRef.current.contentWindow.postMessage(msg, to);
        ctlRef.current = { ...live, status: "loading", time: 0, duration: 0 };
        setCtl(ctlRef.current);
        setCurrent({ ref: p.ref, itemId });
        return;
      }
    }
    const auto = autoplayNext.current; autoplayNext.current = false;
    frameSeq.current += 1;
    const pid = E.tidalPid(`${selfId.current}-${frameSeq.current}`);
    setFrame({ key: frameSeq.current, src: c ? E.controlUrl(c, p.ref.embed, origin, auto, pid) : p.ref.embed, ctl: c });
    ctlRef.current = c ? E.initialState(c, auto, pid) : null; setCtl(ctlRef.current);
    setCurrent({ ref: p.ref, itemId });
    const item = itemId ? libRef.current?.items.find((i) => i.id === itemId) : undefined;
    const title = item?.title ?? `${S.PROVIDER_LABEL[p.ref.provider]} · ${p.ref.id}`;
    setPlays((l) => { const n = pushPlay(l, { id: item?.id ?? `${p.ref.provider}:${p.ref.id}`, title, at: Date.now() }); try { storePlays(localStorage, n); } catch { /* private mode */ } return n; });
  };
  // a link handed over by another app (open-with / routine) starts in the player
  const initial = useRef((win.props.url as string) ?? "");
  useEffect(() => { if (initial.current) play(initial.current); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, []);

  const save = () => {
    if (!lib) return;
    const r = S.addToLibrary(lib, url, "", new Date().toISOString(), `s${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`);
    if (r.error) { setError(r.error); return; }
    const p = S.parseStream(url);
    if (p.ok && p.ref.kind !== kind) { setError(`That is a ${p.ref.kind === "audio" ? "music" : "video"} link — save it from ${p.ref.kind === "audio" ? "Music" : "Video"}.`); return; }
    setError(""); change(r.lib); shell.toast(`Saved to ${kind === "video" ? "Video" : "Music"} library`, "ok");
  };

  const [providerFacet, setProviderFacet] = useState("all");
  const [libSort, setLibSort] = useState<LibrarySort>("added");
  const items = useMemo(() => (lib ? sortLibrary(filterByProvider(S.filterLibrary(lib, kind, q), providerFacet), libSort) : []), [lib, kind, q, providerFacet, libSort]);
  const next = () => {
    const cur = current?.itemId ?? null;
    let n: S.LibraryItem | null;
    if (shuffle) {
      const r = S.shuffleNext(items, cur, played.current, loop);
      if (r?.newRound) played.current = [];
      n = r?.item ?? null;
      if (n) played.current = [...played.current, n.id];
    } else n = S.nextIn(items, cur, loop);
    if (!n) return;
    if (cur) history.current = [...history.current.slice(-99), cur];
    play(n.url, n.id);
  };
  const prev = () => {
    const cur = current?.itemId ?? null;
    let n: S.LibraryItem | null = null;
    while (!n && history.current.length) { const id = history.current[history.current.length - 1]; history.current = history.current.slice(0, -1); n = items.find((x) => x.id === id) ?? null; }
    if (!n && !shuffle) n = S.prevIn(items, cur, loop);
    if (n) play(n.url, n.id);
  };
  const nextRef = useRef(next);
  const autoRef = useRef(autoNext);
  useEffect(() => { nextRef.current = next; autoRef.current = autoNext; });

  // messages from OUR iframe only (source + exact origin), fed through the protocol state machine
  useEffect(() => {
    const onMsg = (ev: MessageEvent) => {
      const st = ctlRef.current, fr = frameRef.current;
      if (!st || !fr || ev.source !== fr.contentWindow || !E.originAllowed(st.ctl, ev.origin)) return;
      const r = E.receive(st, ev.data);
      ctlRef.current = r.state;
      for (const m of r.send) fr.contentWindow?.postMessage(m, ev.origin);
      if (r.events.length) setCtl(r.state);
      if (r.events.some((e) => e.type === "status" && e.status === "playing")) announce();
      if (r.events.some((e) => e.type === "ended") && autoRef.current) { autoplayNext.current = true; nextRef.current(); }
    };
    // another Video / Music window started playing → pause ours (embed via its protocol, native media directly)
    const onExclusive = (ev: Event) => {
      const who = (ev as CustomEvent<string>).detail;
      if (who === selfId.current) return;
      const m = mediaRef.current;
      if (m && !m.paused) m.pause();
      const st = ctlRef.current, fr = frameRef.current;
      if (!st || !fr?.contentWindow || !st.connected || !(st.status === "playing" || st.status === "buffering")) return;
      const src = fr.getAttribute("src") ?? "";
      const msg = E.command(st.ctl, { op: "pause" }, "fusion", st), to = E.targetOrigin(st.ctl, src);
      if (msg && to) { fr.contentWindow.postMessage(msg, to); ctlRef.current = E.afterCommand(st, { op: "pause" }); setCtl(ctlRef.current); }
    };
    window.addEventListener("message", onMsg);
    window.addEventListener(EXCLUSIVE, onExclusive);
    return () => { window.removeEventListener("message", onMsg); window.removeEventListener(EXCLUSIVE, onExclusive); };
  }, []);
  function announce() { window.dispatchEvent(new CustomEvent(EXCLUSIVE, { detail: selfId.current })); }
  // YouTube speaks only after a "listening" handshake: repeat it until the player answers (≤ 10 s)
  const onFrameLoad = () => {
    const st = ctlRef.current, fr = frameRef.current, f = frame;
    if (!st || !fr || !f?.ctl) return;
    const to = E.targetOrigin(f.ctl, f.src);
    if (!to) return;
    if (st.oneWay) {
      // TIDAL never speaks first: usable from load; a queued autoplay is retried until the player reports a start
      const r = E.frameLoaded(st);
      ctlRef.current = r.state; setCtl(r.state);
      if (r.send.length) {
        let n = 0;
        const again = () => {
          if (ctlRef.current?.status === "playing" || frameRef.current !== fr || n++ > 8) return;
          for (const m of r.send) fr.contentWindow?.postMessage(m, to);
          setTimeout(again, 750);
        };
        again();
      }
      return;
    }
    const msgs = E.handshake(f.ctl, `fusion-${f.key}`);
    if (!msgs.length) return;
    let n = 0;
    const tick = () => {
      if (ctlRef.current?.connected || frameRef.current !== fr || n++ > 40) return;
      for (const m of msgs) fr.contentWindow?.postMessage(m, to);
      setTimeout(tick, 250);
    };
    tick();
  };
  const send = (c: E.Command) => {
    const st = ctlRef.current, fr = frameRef.current, f = frame;
    if (!st || !fr || !f?.ctl) return;
    const msg = E.command(f.ctl, c, "fusion", st), to = E.targetOrigin(f.ctl, f.src);
    if (msg && to) {
      fr.contentWindow?.postMessage(msg, to);
      const nx = E.afterCommand(st, c);
      if (nx !== st) { ctlRef.current = nx; setCtl(nx); }
    }
  };
  const ref = current?.ref ?? null;
  const loaded = !!ref && (ref.provider === "file" || alwaysLoad || consented.has(ref.host));

  /* ------------------------------------------------ TT34 SM-09/10: one transport for embeds and native files */
  const native = ref?.provider === "file";
  const caps: E.Caps = native ? { seek: true, volume: true, mute: true, rate: true, playlist: false } : E.capabilities(ctl);
  const tp = native
    ? { time: media?.time ?? 0, duration: media?.duration ?? 0, volume: media ? Math.round(media.volume * 100) : undefined, muted: media?.muted, rate: media?.rate, rates: E.DEFAULT_RATES as readonly number[], playing: media ? !media.paused : false }
    : { time: ctl?.time ?? 0, duration: ctl?.duration ?? 0, volume: ctl?.volume, muted: ctl?.muted, rate: ctl?.rate, rates: (ctl?.rates?.length ? ctl.rates : E.DEFAULT_RATES) as readonly number[], playing: ctl?.status === "playing" || ctl?.status === "buffering" };
  const syncMedia = (el: HTMLMediaElement) => setMedia({ time: el.currentTime, duration: Number.isFinite(el.duration) ? el.duration : 0, volume: el.volume, muted: el.muted, rate: el.playbackRate, paused: el.paused });
