    if (n.nodeType === 3) { const t = (n as Text).data.replace(/\s+/g, " "); if (!t.trim() && !cur) return; if (!cur) { cur = { runs: [] }; out.push(cur); } cur.runs.push({ text: t, ...f }); return; }
